impl dclCorrectionT {
    pub fn pack<'b, A: ::flatbuffers::Allocator + 'b>(
        &self,
        _fbb: &mut ::flatbuffers::FlatBufferBuilder<'b, A>
    ) -> ::flatbuffers::WIPOffset<dclCorrection<'b>> {
        let FORM = self.FORM;
        let DEGREE = self.DEGREE;
        let SEGMENTS = self.SEGMENTS.as_ref().map(|x|{
            let w: alloc::vec::Vec<_> = x.iter().map(|t| t.pack(_fbb)).collect();_fbb.create_vector(&w)
        });
        let NODE_TIMES_MS = self.NODE_TIMES_MS.as_ref().map(|x|{
            _fbb.create_vector(x)
        });
        let NODE_ALTITUDES_KM = self.NODE_ALTITUDES_KM.as_ref().map(|x|{
            _fbb.create_vector(x)
        });
        let NODE_VALUES_K = self.NODE_VALUES_K.as_ref().map(|x|{
            _fbb.create_vector(x)
        });
        let NODE_SIGMAS_K = self.NODE_SIGMAS_K.as_ref().map(|x|{
            _fbb.create_vector(x)
        });
        let NODE_LOG_DENSITY_SCALE_DIMENSIONLESS = self.NODE_LOG_DENSITY_SCALE_DIMENSIONLESS.as_ref().map(|x|{
            _fbb.create_vector(x)
        });
        dclCorrection::create(_fbb, &dclCorrectionArgs{
            FORM,
            DEGREE,
            SEGMENTS,
            NODE_TIMES_MS,
            NODE_ALTITUDES_KM,
            NODE_VALUES_K,
            NODE_SIGMAS_K,
            NODE_LOG_DENSITY_SCALE_DIMENSIONLESS,
        })
    }
}

