pub struct dclRefusalArgs<'a> {
    pub INDEX: u32,
    pub REASON: Option<::flatbuffers::WIPOffset<&'a str>>,
}

impl<'a> Default for dclRefusalArgs<'a> {
    #[inline]
    fn default() -> Self {
        dclRefusalArgs {
            INDEX: 0,
            REASON: None,
        }
    }
}

pub struct dclRefusalBuilder<'a: 'b, 'b, A: ::flatbuffers::Allocator + 'a> {
    fbb_: &'b mut ::flatbuffers::FlatBufferBuilder<'a, A>,
    start_: ::flatbuffers::WIPOffset<::flatbuffers::TableUnfinishedWIPOffset>,
}

impl<'a: 'b, 'b, A: ::flatbuffers::Allocator + 'a> dclRefusalBuilder<'a, 'b, A> {
    #[inline]
    pub fn add_INDEX(&mut self, INDEX: u32) {
        self.fbb_.push_slot::<u32>(dclRefusal::VT_INDEX, INDEX, 0);
    }

    #[inline]
    pub fn add_REASON(&mut self, REASON: ::flatbuffers::WIPOffset<&'b  str>) {
        self.fbb_.push_slot_always::<::flatbuffers::WIPOffset<_>>(dclRefusal::VT_REASON, REASON);
    }

    #[inline]
    pub fn new(_fbb: &'b mut ::flatbuffers::FlatBufferBuilder<'a, A>) -> dclRefusalBuilder<'a, 'b, A> {
        let start = _fbb.start_table();
        dclRefusalBuilder {
            fbb_: _fbb,
            start_: start,
        }
    }

    #[inline]
    pub fn finish(self) -> ::flatbuffers::WIPOffset<dclRefusal<'a>> {
        let o = self.fbb_.end_table(self.start_);
        ::flatbuffers::WIPOffset::new(o.value())
    }
}

impl ::core::fmt::Debug for dclRefusal<'_> {
    fn fmt(&self, f: &mut ::core::fmt::Formatter<'_>) -> ::core::fmt::Result {
        let mut ds = f.debug_struct("dclRefusal");
        ds.field("INDEX", &self.INDEX());
        ds.field("REASON", &self.REASON());
        ds.finish()
    }
}

#[non_exhaustive]
#[derive(Debug, Clone, PartialEq)]
pub struct dclRefusalT {
    pub INDEX: u32,
    pub REASON: Option<alloc::string::String>,
}

impl Default for dclRefusalT {
    fn default() -> Self {
        Self {
            INDEX: 0,
            REASON: None,
        }
    }
}

impl dclRefusalT {
    pub fn pack<'b, A: ::flatbuffers::Allocator + 'b>(
        &self,
        _fbb: &mut ::flatbuffers::FlatBufferBuilder<'b, A>
    ) -> ::flatbuffers::WIPOffset<dclRefusal<'b>> {
        let INDEX = self.INDEX;
        let REASON = self.REASON.as_ref().map(|x|{
            _fbb.create_string(x)
        });
        dclRefusal::create(_fbb, &dclRefusalArgs{
            INDEX,
            REASON,
        })
    }
}

pub enum dclObjectOffset {}

/// One object's element-set history and its decay.
#[derive(Copy, Clone, PartialEq)]
pub struct dclObject<'a> {
    pub _tab: ::flatbuffers::Table<'a>,
}

impl<'a> ::flatbuffers::Follow<'a> for dclObject<'a> {
    type Inner = dclObject<'a>;

    #[inline]
    unsafe fn follow(buf: &'a [u8], loc: usize) -> Self::Inner {
        Self { _tab: unsafe { ::flatbuffers::Table::new(buf, loc) } }
    }
}

