    #[inline]
    pub unsafe fn init_from_table(table: ::flatbuffers::Table<'a>) -> Self {
        dclObject { _tab: table }
    }

    #[allow(unused_mut)]
    pub fn create<'bldr: 'args, 'args: 'mut_bldr, 'mut_bldr, A: ::flatbuffers::Allocator + 'bldr>(
        _fbb: &'mut_bldr mut ::flatbuffers::FlatBufferBuilder<'bldr, A>,
        args: &'args dclObjectArgs<'args>
    ) -> ::flatbuffers::WIPOffset<dclObject<'bldr>> {
        let mut builder = dclObjectBuilder::new(_fbb);
        builder.add_MODEL_DECAY_M(args.MODEL_DECAY_M);
        builder.add_OBSERVED_DECAY_M(args.OBSERVED_DECAY_M);
        builder.add_LAST_MS(args.LAST_MS);
        builder.add_FIRST_MS(args.FIRST_MS);
        builder.add_RESIDUAL_SCALE_M(args.RESIDUAL_SCALE_M);
        builder.add_LN_B_SIGMA(args.LN_B_SIGMA);
        builder.add_LN_B(args.LN_B);
        builder.add_MEAN_ALTITUDE_KM(args.MEAN_ALTITUDE_KM);
        builder.add_LN_B_PRIOR_SIGMA(args.LN_B_PRIOR_SIGMA);
        builder.add_LN_B_PRIOR_MEAN(args.LN_B_PRIOR_MEAN);
        builder.add_SPAN_S(args.SPAN_S);
        builder.add_BALLISTIC_COEFFICIENT_M2_KG(args.BALLISTIC_COEFFICIENT_M2_KG);
        if let Some(x) = args.SAMPLE_DECAY_FACTOR_M2_S { builder.add_SAMPLE_DECAY_FACTOR_M2_S(x); }
        if let Some(x) = args.SAMPLE_DENSITY_KG_M3 { builder.add_SAMPLE_DENSITY_KG_M3(x); }
        if let Some(x) = args.SAMPLE_ALTITUDE_KM { builder.add_SAMPLE_ALTITUDE_KM(x); }
        if let Some(x) = args.SAMPLE_LONGITUDE_DEG { builder.add_SAMPLE_LONGITUDE_DEG(x); }
        if let Some(x) = args.SAMPLE_LATITUDE_DEG { builder.add_SAMPLE_LATITUDE_DEG(x); }
        if let Some(x) = args.SAMPLE_TEME_STATE { builder.add_SAMPLE_TEME_STATE(x); }
        if let Some(x) = args.SAMPLE_TIME_MS { builder.add_SAMPLE_TIME_MS(x); }
        if let Some(x) = args.FIT { builder.add_FIT(x); }
        builder.add_SETS_IN_CHAINS(args.SETS_IN_CHAINS);
        builder.add_CHAINS(args.CHAINS);
        if let Some(x) = args.SEGMENT_MEAN_ALTITUDE_KM { builder.add_SEGMENT_MEAN_ALTITUDE_KM(x); }
        if let Some(x) = args.SEGMENT_DECAY_M { builder.add_SEGMENT_DECAY_M(x); }
        if let Some(x) = args.SEGMENT_TO_MS { builder.add_SEGMENT_TO_MS(x); }
        if let Some(x) = args.SEGMENT_FROM_MS { builder.add_SEGMENT_FROM_MS(x); }
        if let Some(x) = args.SET_USED { builder.add_SET_USED(x); }
        if let Some(x) = args.SET_RESIDUAL_M { builder.add_SET_RESIDUAL_M(x); }
        if let Some(x) = args.SET_CUMULATIVE_DECAY_M { builder.add_SET_CUMULATIVE_DECAY_M(x); }
        if let Some(x) = args.SET_ECCENTRICITY { builder.add_SET_ECCENTRICITY(x); }
        if let Some(x) = args.SET_PERIGEE_HEIGHT_KM { builder.add_SET_PERIGEE_HEIGHT_KM(x); }
        if let Some(x) = args.SET_MEAN_SEMI_MAJOR_AXIS_KM { builder.add_SET_MEAN_SEMI_MAJOR_AXIS_KM(x); }
        if let Some(x) = args.SET_TIME_MS { builder.add_SET_TIME_MS(x); }
        if let Some(x) = args.REFUSED { builder.add_REFUSED(x); }
        if let Some(x) = args.SKIPPED_REASON { builder.add_SKIPPED_REASON(x); }
        if let Some(x) = args.ELEMENT_SETS { builder.add_ELEMENT_SETS(x); }
        if let Some(x) = args.ID { builder.add_ID(x); }
        builder.add_OK(args.OK);
        builder.finish()
    }

    pub fn unpack(&self) -> dclObjectT {
        let ID = self.ID().map(|x| {
            alloc::string::ToString::to_string(x)
        });
        let ELEMENT_SETS = self.ELEMENT_SETS().map(|x| {
            x.iter().map(|t| t.unpack()).collect()
        });
        let BALLISTIC_COEFFICIENT_M2_KG = self.BALLISTIC_COEFFICIENT_M2_KG();
        let SPAN_S = self.SPAN_S();
        let LN_B_PRIOR_MEAN = self.LN_B_PRIOR_MEAN();
        let LN_B_PRIOR_SIGMA = self.LN_B_PRIOR_SIGMA();
        let OK = self.OK();
        let SKIPPED_REASON = self.SKIPPED_REASON().map(|x| {
            alloc::string::ToString::to_string(x)
        });
        let REFUSED = self.REFUSED().map(|x| {
            x.iter().map(|t| t.unpack()).collect()
        });
        let SET_TIME_MS = self.SET_TIME_MS().map(|x| {
            x.into_iter().collect()
        });
        let SET_MEAN_SEMI_MAJOR_AXIS_KM = self.SET_MEAN_SEMI_MAJOR_AXIS_KM().map(|x| {
            x.into_iter().collect()
        });
        let SET_PERIGEE_HEIGHT_KM = self.SET_PERIGEE_HEIGHT_KM().map(|x| {
            x.into_iter().collect()
        });
        let SET_ECCENTRICITY = self.SET_ECCENTRICITY().map(|x| {
            x.into_iter().collect()
        });
        let SET_CUMULATIVE_DECAY_M = self.SET_CUMULATIVE_DECAY_M().map(|x| {
            x.into_iter().collect()
        });
        let SET_RESIDUAL_M = self.SET_RESIDUAL_M().map(|x| {
            x.into_iter().collect()
        });
        let SET_USED = self.SET_USED().map(|x| {
            x.into_iter().collect()
        });
        let SEGMENT_FROM_MS = self.SEGMENT_FROM_MS().map(|x| {
            x.into_iter().collect()
        });
        let SEGMENT_TO_MS = self.SEGMENT_TO_MS().map(|x| {
            x.into_iter().collect()
        });
        let SEGMENT_DECAY_M = self.SEGMENT_DECAY_M().map(|x| {
            x.into_iter().collect()
        });
        let SEGMENT_MEAN_ALTITUDE_KM = self.SEGMENT_MEAN_ALTITUDE_KM().map(|x| {
            x.into_iter().collect()
        });
        let MEAN_ALTITUDE_KM = self.MEAN_ALTITUDE_KM();
        let LN_B = self.LN_B();
        let LN_B_SIGMA = self.LN_B_SIGMA();
        let RESIDUAL_SCALE_M = self.RESIDUAL_SCALE_M();
        let CHAINS = self.CHAINS();
        let SETS_IN_CHAINS = self.SETS_IN_CHAINS();
        let FIRST_MS = self.FIRST_MS();
        let LAST_MS = self.LAST_MS();
        let OBSERVED_DECAY_M = self.OBSERVED_DECAY_M();
        let MODEL_DECAY_M = self.MODEL_DECAY_M();
        let FIT = self.FIT().map(|x| {
            alloc::boxed::Box::new(x.unpack())
        });
        let SAMPLE_TIME_MS = self.SAMPLE_TIME_MS().map(|x| {
            x.into_iter().collect()
        });
        let SAMPLE_TEME_STATE = self.SAMPLE_TEME_STATE().map(|x| {
            x.into_iter().collect()
        });
        let SAMPLE_LATITUDE_DEG = self.SAMPLE_LATITUDE_DEG().map(|x| {
            x.into_iter().collect()
        });
        let SAMPLE_LONGITUDE_DEG = self.SAMPLE_LONGITUDE_DEG().map(|x| {
            x.into_iter().collect()
        });
        let SAMPLE_ALTITUDE_KM = self.SAMPLE_ALTITUDE_KM().map(|x| {
            x.into_iter().collect()
        });
        let SAMPLE_DENSITY_KG_M3 = self.SAMPLE_DENSITY_KG_M3().map(|x| {
            x.into_iter().collect()
        });
        let SAMPLE_DECAY_FACTOR_M2_S = self.SAMPLE_DECAY_FACTOR_M2_S().map(|x| {
            x.into_iter().collect()
        });
        dclObjectT {
            ID,
            ELEMENT_SETS,
            BALLISTIC_COEFFICIENT_M2_KG,
            SPAN_S,
            LN_B_PRIOR_MEAN,
            LN_B_PRIOR_SIGMA,
            OK,
            SKIPPED_REASON,
            REFUSED,
            SET_TIME_MS,
            SET_MEAN_SEMI_MAJOR_AXIS_KM,
            SET_PERIGEE_HEIGHT_KM,
            SET_ECCENTRICITY,
            SET_CUMULATIVE_DECAY_M,
            SET_RESIDUAL_M,
            SET_USED,
            SEGMENT_FROM_MS,
            SEGMENT_TO_MS,
            SEGMENT_DECAY_M,
            SEGMENT_MEAN_ALTITUDE_KM,
            MEAN_ALTITUDE_KM,
            LN_B,
            LN_B_SIGMA,
            RESIDUAL_SCALE_M,
            CHAINS,
            SETS_IN_CHAINS,
            FIRST_MS,
            LAST_MS,
            OBSERVED_DECAY_M,
            MODEL_DECAY_M,
            FIT,
            SAMPLE_TIME_MS,
            SAMPLE_TEME_STATE,
            SAMPLE_LATITUDE_DEG,
            SAMPLE_LONGITUDE_DEG,
            SAMPLE_ALTITUDE_KM,
            SAMPLE_DENSITY_KG_M3,
            SAMPLE_DECAY_FACTOR_M2_S,
        }
    }

