impl ::flatbuffers::Verifiable for dclIteration<'_> {
    #[inline]
    fn run_verifier(
        v: &mut ::flatbuffers::Verifier, pos: usize
    ) -> Result<(), ::flatbuffers::InvalidFlatbuffer> {
        v.visit_table(pos)?
            .visit_field::<u32>("ITERATION", Self::VT_ITERATION, false)?
            .visit_field::<f64>("CHI_SQUARE", Self::VT_CHI_SQUARE, false)?
            .visit_field::<u32>("OBSERVATIONS", Self::VT_OBSERVATIONS, false)?
            .visit_field::<f64>("MAX_STEP_K", Self::VT_MAX_STEP_K, false)?
            .visit_field::<f64>("MAX_STEP_LN_B", Self::VT_MAX_STEP_LN_B, false)?
            .visit_field::<f64>("MAX_STEP_OFFSET_M", Self::VT_MAX_STEP_OFFSET_M, false)?
            .finish();
        Ok(())
    }
}

