    pub const VT_CORRECTION: ::flatbuffers::VOffsetT = 32;
    pub const VT_STATUS: ::flatbuffers::VOffsetT = 34;
    pub const VT_ERROR_CODE: ::flatbuffers::VOffsetT = 36;
    pub const VT_ERROR_MESSAGE: ::flatbuffers::VOffsetT = 38;
    pub const VT_POINTS: ::flatbuffers::VOffsetT = 40;
    pub const VT_OBJECTS: ::flatbuffers::VOffsetT = 42;
    pub const VT_FIT: ::flatbuffers::VOffsetT = 44;
    pub const VT_LEVELS: ::flatbuffers::VOffsetT = 46;
    pub const VT_HISTORY: ::flatbuffers::VOffsetT = 48;
    pub const VT_LEVEL_LN_B_CORRELATION: ::flatbuffers::VOffsetT = 50;
    pub const VT_MEAN_LEVEL_SIGMA_K: ::flatbuffers::VOffsetT = 52;
    pub const VT_STATES: ::flatbuffers::VOffsetT = 54;
    pub const VT_PROVENANCE: ::flatbuffers::VOffsetT = 56;

    #[inline]
    pub unsafe fn init_from_table(table: ::flatbuffers::Table<'a>) -> Self {
        DCL { _tab: table }
    }

    #[allow(unused_mut)]
    pub fn create<'bldr: 'args, 'args: 'mut_bldr, 'mut_bldr, A: ::flatbuffers::Allocator + 'bldr>(
        _fbb: &'mut_bldr mut ::flatbuffers::FlatBufferBuilder<'bldr, A>,
        args: &'args DCLArgs<'args>
    ) -> ::flatbuffers::WIPOffset<DCL<'bldr>> {
        let mut builder = DCLBuilder::new(_fbb);
        builder.add_MEAN_LEVEL_SIGMA_K(args.MEAN_LEVEL_SIGMA_K);
        builder.add_LEVEL_LN_B_CORRELATION(args.LEVEL_LN_B_CORRELATION);
        builder.add_BALLISTIC_COEFFICIENT_M2_KG(args.BALLISTIC_COEFFICIENT_M2_KG);
        builder.add_EARTH_ROTATION_RAD_S(args.EARTH_ROTATION_RAD_S);
        builder.add_GM_M3_S2(args.GM_M3_S2);
        builder.add_CREATED_AT_MS(args.CREATED_AT_MS);
        if let Some(x) = args.PROVENANCE { builder.add_PROVENANCE(x); }
        if let Some(x) = args.STATES { builder.add_STATES(x); }
        if let Some(x) = args.HISTORY { builder.add_HISTORY(x); }
        if let Some(x) = args.LEVELS { builder.add_LEVELS(x); }
        if let Some(x) = args.FIT { builder.add_FIT(x); }
        if let Some(x) = args.OBJECTS { builder.add_OBJECTS(x); }
        if let Some(x) = args.POINTS { builder.add_POINTS(x); }
        if let Some(x) = args.ERROR_MESSAGE { builder.add_ERROR_MESSAGE(x); }
        if let Some(x) = args.ERROR_CODE { builder.add_ERROR_CODE(x); }
        if let Some(x) = args.CORRECTION { builder.add_CORRECTION(x); }
        if let Some(x) = args.SETTINGS { builder.add_SETTINGS(x); }
        if let Some(x) = args.GRAVITY_FIELD { builder.add_GRAVITY_FIELD(x); }
        if let Some(x) = args.SPACE_WEATHER { builder.add_SPACE_WEATHER(x); }
        if let Some(x) = args.JB2008_DRIVERS { builder.add_JB2008_DRIVERS(x); }
        if let Some(x) = args.ATMOSPHERE { builder.add_ATMOSPHERE(x); }
        if let Some(x) = args.PRODUCER { builder.add_PRODUCER(x); }
        if let Some(x) = args.ID { builder.add_ID(x); }
        builder.add_GRAVITY_ORDER(args.GRAVITY_ORDER);
        builder.add_GRAVITY_DEGREE(args.GRAVITY_DEGREE);
        builder.add_STATUS(args.STATUS);
        builder.add_PRODUCT(args.PRODUCT);
        builder.finish()
    }

    pub fn unpack(&self) -> DCLT {
        let ID = self.ID().map(|x| {
            alloc::string::ToString::to_string(x)
        });
        let CREATED_AT_MS = self.CREATED_AT_MS();
        let PRODUCER = self.PRODUCER().map(|x| {
            alloc::string::ToString::to_string(x)
        });
        let PRODUCT = self.PRODUCT();
        let ATMOSPHERE = self.ATMOSPHERE().map(|x| {
            alloc::boxed::Box::new(x.unpack())
        });
        let JB2008_DRIVERS = self.JB2008_DRIVERS().map(|x| {
            alloc::boxed::Box::new(x.unpack())
        });
        let SPACE_WEATHER = self.SPACE_WEATHER().map(|x| {
            x.iter().map(|t| t.unpack()).collect()
        });
        let GRAVITY_FIELD = self.GRAVITY_FIELD().map(|x| {
            alloc::string::ToString::to_string(x)
        });
        let GRAVITY_DEGREE = self.GRAVITY_DEGREE();
        let GRAVITY_ORDER = self.GRAVITY_ORDER();
        let GM_M3_S2 = self.GM_M3_S2();
        let EARTH_ROTATION_RAD_S = self.EARTH_ROTATION_RAD_S();
        let BALLISTIC_COEFFICIENT_M2_KG = self.BALLISTIC_COEFFICIENT_M2_KG();
        let SETTINGS = self.SETTINGS().map(|x| {
            alloc::boxed::Box::new(x.unpack())
        });
        let CORRECTION = self.CORRECTION().map(|x| {
            alloc::boxed::Box::new(x.unpack())
        });
        let STATUS = self.STATUS();
        let ERROR_CODE = self.ERROR_CODE().map(|x| {
            alloc::string::ToString::to_string(x)
        });
        let ERROR_MESSAGE = self.ERROR_MESSAGE().map(|x| {
            alloc::string::ToString::to_string(x)
        });
        let POINTS = self.POINTS().map(|x| {
            alloc::boxed::Box::new(x.unpack())
        });
        let OBJECTS = self.OBJECTS().map(|x| {
            x.iter().map(|t| t.unpack()).collect()
        });
        let FIT = self.FIT().map(|x| {
            alloc::boxed::Box::new(x.unpack())
        });
        let LEVELS = self.LEVELS().map(|x| {
            x.iter().map(|t| t.unpack()).collect()
        });
        let HISTORY = self.HISTORY().map(|x| {
            x.iter().map(|t| t.unpack()).collect()
        });
        let LEVEL_LN_B_CORRELATION = self.LEVEL_LN_B_CORRELATION();
        let MEAN_LEVEL_SIGMA_K = self.MEAN_LEVEL_SIGMA_K();
        let STATES = self.STATES().map(|x| {
            alloc::boxed::Box::new(x.unpack())
        });
        let PROVENANCE = self.PROVENANCE().map(|x| {
            alloc::boxed::Box::new(x.unpack())
        });
        DCLT {
            ID,
            CREATED_AT_MS,
            PRODUCER,
            PRODUCT,
            ATMOSPHERE,
            JB2008_DRIVERS,
            SPACE_WEATHER,
            GRAVITY_FIELD,
            GRAVITY_DEGREE,
            GRAVITY_ORDER,
            GM_M3_S2,
            EARTH_ROTATION_RAD_S,
            BALLISTIC_COEFFICIENT_M2_KG,
            SETTINGS,
            CORRECTION,
            STATUS,
            ERROR_CODE,
            ERROR_MESSAGE,
            POINTS,
            OBJECTS,
            FIT,
            LEVELS,
            HISTORY,
            LEVEL_LN_B_CORRELATION,
            MEAN_LEVEL_SIGMA_K,
            STATES,
            PROVENANCE,
        }
    }

