/// Verifies that a buffer of bytes contains a `DCL`
/// and returns it.
/// Note that verification is still experimental and may not
/// catch every error, or be maximally performant. For the
/// previous, unchecked, behavior use
/// `root_as_dcl_unchecked`.
#[inline]
pub fn root_as_dcl(buf: &[u8]) -> Result<DCL<'_>, ::flatbuffers::InvalidFlatbuffer> {
    ::flatbuffers::root::<DCL>(buf)
}

/// Verifies that a buffer of bytes contains a size prefixed
/// `DCL` and returns it.
/// Note that verification is still experimental and may not
/// catch every error, or be maximally performant. For the
/// previous, unchecked, behavior use
/// `size_prefixed_root_as_dcl_unchecked`.
#[inline]
pub fn size_prefixed_root_as_dcl(buf: &[u8]) -> Result<DCL<'_>, ::flatbuffers::InvalidFlatbuffer> {
    ::flatbuffers::size_prefixed_root::<DCL>(buf)
}

/// Verifies, with the given options, that a buffer of bytes
/// contains a `DCL` and returns it.
/// Note that verification is still experimental and may not
/// catch every error, or be maximally performant. For the
/// previous, unchecked, behavior use
/// `root_as_dcl_unchecked`.
#[inline]
pub fn root_as_dcl_with_opts<'b, 'o>(
    opts: &'o ::flatbuffers::VerifierOptions,
    buf: &'b [u8],
) -> Result<DCL<'b>, ::flatbuffers::InvalidFlatbuffer> {
    ::flatbuffers::root_with_opts::<DCL<'b>>(opts, buf)
}

/// Verifies, with the given verifier options, that a buffer of
/// bytes contains a size prefixed `DCL` and returns
/// it. Note that verification is still experimental and may not
/// catch every error, or be maximally performant. For the
/// previous, unchecked, behavior use
/// `root_as_dcl_unchecked`.
#[inline]
pub fn size_prefixed_root_as_dcl_with_opts<'b, 'o>(
    opts: &'o ::flatbuffers::VerifierOptions,
    buf: &'b [u8],
) -> Result<DCL<'b>, ::flatbuffers::InvalidFlatbuffer> {
    ::flatbuffers::size_prefixed_root_with_opts::<DCL<'b>>(opts, buf)
}

/// Assumes, without verification, that a buffer of bytes contains a DCL and returns it.
/// # Safety
/// Callers must trust the given bytes do indeed contain a valid `DCL`.
#[inline]
pub unsafe fn root_as_dcl_unchecked(buf: &[u8]) -> DCL<'_> {
    unsafe { ::flatbuffers::root_unchecked::<DCL>(buf) }
}

/// Assumes, without verification, that a buffer of bytes contains a size prefixed DCL and returns it.
/// # Safety
/// Callers must trust the given bytes do indeed contain a valid size prefixed `DCL`.
#[inline]
pub unsafe fn size_prefixed_root_as_dcl_unchecked(buf: &[u8]) -> DCL<'_> {
    unsafe { ::flatbuffers::size_prefixed_root_unchecked::<DCL>(buf) }
}

pub const DCL_IDENTIFIER: &str = "$DCL";

#[inline]
pub fn dcl_buffer_has_identifier(buf: &[u8]) -> bool {
    ::flatbuffers::buffer_has_identifier(buf, DCL_IDENTIFIER, false)
}

#[inline]
pub fn dcl_size_prefixed_buffer_has_identifier(buf: &[u8]) -> bool {
    ::flatbuffers::buffer_has_identifier(buf, DCL_IDENTIFIER, true)
}

#[inline]
pub fn finish_dcl_buffer<'a, 'b, A: ::flatbuffers::Allocator + 'a>(
    fbb: &'b mut ::flatbuffers::FlatBufferBuilder<'a, A>,
    root: ::flatbuffers::WIPOffset<DCL<'a>>
) {
    fbb.finish(root, Some(DCL_IDENTIFIER));
}

#[inline]
pub fn finish_size_prefixed_dcl_buffer<'a, 'b, A: ::flatbuffers::Allocator + 'a>(
    fbb: &'b mut ::flatbuffers::FlatBufferBuilder<'a, A>,
    root: ::flatbuffers::WIPOffset<DCL<'a>>
) {
    fbb.finish_size_prefixed(root, Some(DCL_IDENTIFIER));
}
